// Original editable vector objects; no external graphics or fonts.
import {SOILS} from './model.js';
export const svg=(body,box='0 0 200 200',extra='')=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${box}" fill="none" ${extra}>${body}</svg>`;
export function glyph(name){
 const paths={undo:'M9 10H3V4m0 6a9 9 0 1 1 0 8',reset:'M4 10a8 8 0 1 1 1 9M4 4v6h6',play:'m9 5 11 7-11 7Z',pause:'M8 5v14M16 5v14',next:'m8 6 7 6-7 6M19 6v12',check:'m5 12 5 5L20 7',close:'m6 6 12 12M18 6 6 18',drop:'M12 3C9 7 5 12 5 16a7 7 0 0 0 14 0c0-4-4-9-7-13Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',hand:'M9 13V5a2 2 0 0 1 4 0v6-3a2 2 0 0 1 4 0v4-1a2 2 0 0 1 4 0v5c0 5-3 7-7 7-3 0-4-2-6-4l-4-4a2 2 0 0 1 3-3l2 1Z',leaf:'M5 19C0 5 12 1 21 3c1 9-2 20-15 16Zm0 3L17 7'};
 return svg(`<path d="${paths[name]||paths.leaf}" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" ${name==='play'?'fill="currentColor"':''}/>`, '0 0 24 24','aria-hidden="true"');
}
export function plant(type,health=90){
 const c=health<30?['#aa9868','#83764e','#d0bd83']:health<60?['#8a9b66','#667b50','#b4bd82']:['#648d58','#365f48','#a0b879'];
 const leaf=(x,y,l,w,a,color)=>`<g transform="translate(${x} ${y}) rotate(${a})"><path d="M0 0C${-w} ${-l*.2} ${-w*.9} ${-l*.75} 0 ${-l}C${w*.9} ${-l*.8} ${w} ${-l*.2} 0 0Z" fill="${color}"/><path d="M0 0V${-l*.86}" stroke="#e3e9bd" stroke-width=".65" opacity=".65"/></g>`;
 if(type==='moss')return `<ellipse cx="0" cy="-4" rx="57" ry="13" fill="#385d43"/>${Array.from({length:24},(_,i)=>{const x=-49+(i*31%100),y=-5-(i*13%19);return `<path d="M${x-9} ${y+6}q-6-13 1-18q8-11 15 0q10 2 6 15Z" fill="${c[i%3]}"/><path d="M${x+1} ${y+3}v-12m0 4-4-4m4 6 5-5" stroke="#d7e0ac" stroke-width=".7" opacity=".65"/>`;}).join('')}`;
 if(type==='fern')return [[-60,99],[-29,132],[0,155],[38,132],[68,95]].map(([a,h],k)=>`<g transform="rotate(${a*.7})"><path d="M0 0Q-13 ${-h*.5} 0 ${-h}" stroke="${c[1]}" stroke-width="1.7"/>${Array.from({length:8},(_,i)=>{const t=.15+i*.1,y=-h*t,x=-5*Math.sin(t*Math.PI),len=30*Math.sin(t*Math.PI)+3;return leaf(x,y,len,6,-65,c[(i+k)%3])+leaf(x,y-4,len,6,65,c[(i+k+1)%3]);}).join('')}</g>`).join('');
 return [[-35,103],[4,147],[38,111]].map(([a,h],k)=>`<g transform="rotate(${a*.55})"><path d="M0 0Q12 ${-h*.6} 0 ${-h}" stroke="${c[1]}" stroke-width="2"/>${[.24,.47,.7].map((t,i)=>leaf(5,-h*t,41-i*4,15,-57,c[(k+i)%3])+leaf(6,-h*t-10,37-i*3,14,55,c[(k+i+1)%3])).join('')}${leaf(0,-h*.86,27,11,0,c[0])}</g>`).join('');
}
export function pottedPlant(type){return svg(`<ellipse cx="100" cy="185" rx="45" ry="7" fill="#5f6340" opacity=".12"/><g transform="translate(100 150) scale(.83)">${plant(type)}</g><path d="M67 146h66l-8 35q-25 10-50 0Z" fill="${type==='fern'?'#c29773':type==='moss'?'#d3c9a7':'#b78670'}"/><path d="M65 145q35-8 70 0v9q-35 8-70 0Z" fill="${type==='fern'?'#d2ab86':type==='moss'?'#dfd6b8':'#c99a83'}"/><path d="M76 158l5 20" stroke="#fff" opacity=".25" stroke-width="3"/>`);}
export function soilTray(type){const color=SOILS[type].color;return svg(`<ellipse cx="100" cy="124" rx="80" ry="20" fill="#62623e" opacity=".12"/><path d="m18 77 15 48q67 24 134 0l15-48" fill="#c6b998" stroke="#9e977c" stroke-width="1.5"/><ellipse cx="100" cy="78" rx="82" ry="27" fill="#e4d9bb" stroke="#b5aa8b" stroke-width="2"/><ellipse cx="100" cy="79" rx="72" ry="21" fill="${color}"/>${Array.from({length:29},(_,i)=>`<ellipse cx="${39+i*29%121}" cy="${68+i*11%21}" rx="${1+i%3}" ry="${1+i%2}" fill="${i%3?'#d6bd91':'#493e30'}" opacity=".65"/>`).join('')}${type==='humus'?'<path d="m67 80 12-7m19 12 10 3m23-13 9 5" stroke="#303c24" stroke-width="3"/>':''}`, '0 0 200 150');}
export function trowel(soil=null){return svg(`<g transform="rotate(35 100 100)"><path d="M89 82V19q11-8 22 0v63" fill="#b89065" stroke="#8b6f50" stroke-width="2"/><path d="M94 23v48" stroke="#d9b891" stroke-width="3" stroke-linecap="round"/><path d="M94 75h12v30H94Z" fill="#a6ada1"/><path d="M78 101q22-11 44 0l6 35q1 31-28 47-29-16-28-47Z" fill="#c5cfc2" stroke="#8c9c8f" stroke-width="2"/><path d="M100 108v60" stroke="#e9eee4" stroke-width="3"/>${soil?`<path d="M78 124q23-14 45 0v19q-7 21-23 29-17-9-23-29Z" fill="${SOILS[soil].color}"/>`:''}</g>`);}
export function bug(type,x=0,y=0,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})">${type==='springtails'?'<ellipse rx="14" ry="7" fill="#dedbc1" stroke="#8b9877"/><circle cx="17" cy="-3" r="5" fill="#e9e5d1" stroke="#8b9877"/><path d="m-9 5-6 6m13-6-2 7m12-9 7 5m2-14 7-8m-5 9 10-3" stroke="#8b9877" stroke-width="1.5"/><circle cx="19" cy="-4" r="1" fill="#526144"/>':'<ellipse rx="17" ry="11" fill="#89917b" stroke="#576751"/><path d="M-9-8v16m6-18v20m6-20v20m6-18v16M-12 8l-5 5m14-3v6m10-8 5 5m5-14 7-5m-7 0 5-6" stroke="#52634a" stroke-width="1.5"/><path d="M-11-4q11-8 22 0" stroke="#c5c9ac" stroke-width="2"/>'}</g>`;}
export function bugBox(type){return svg(`<ellipse cx="100" cy="158" rx="70" ry="9" fill="#566348" opacity=".14"/><path d="M30 57v83q70 29 140 0V57" fill="#e7e8cf" fill-opacity=".65" stroke="#9eac8e" stroke-width="2"/><path d="M32 121q68-15 136 0v18q-68 26-136 0Z" fill="#a79e76"/><ellipse cx="100" cy="57" rx="70" ry="21" fill="#c6cdb0" stroke="#97a487" stroke-width="2"/>${Array.from({length:12},(_,i)=>`<ellipse cx="${51+i*23%98}" cy="${48+i*7%16}" rx="2" ry="1.3" fill="#8d9b7a"/>`).join('')}${bug(type,80,113,.95)}${bug(type,126,125,.7)}<path d="M42 76v35" stroke="white" stroke-width="5" stroke-linecap="round" opacity=".55"/>`, '0 0 200 180');}
export function sprayer(){return svg(`<ellipse cx="95" cy="183" rx="55" ry="9" fill="#3d6256" opacity=".12"/><path d="M72 57v20q-27 15-28 43v47q50 19 100 0v-47q-1-28-28-43V57" fill="#b8d2c5" stroke="#6b9687" stroke-width="2"/><path d="M46 128q50 13 96 0v38q-49 17-96 0Z" fill="#8eb9ad" opacity=".6"/><path d="M72 43h47v20H72Z" fill="#597c68"/><path d="M80 43V27h49l29 13v13h-35l-13-10" fill="#d2d7ba" stroke="#8e9e7f" stroke-width="2"/><path d="m127 53-13 24h-10l8-24" fill="#75907a"/><path d="M68 99q-9 14-9 43" stroke="#fff" stroke-width="7" stroke-linecap="round" opacity=".45"/><path d="M83 116q12-22 24 0a12 12 0 0 1-24 0Z" fill="none" stroke="#628f7e" stroke-width="2"/>`);}
export function lamp(level,active){return svg(`<path d="M100 0v55" stroke="#7b876f" stroke-width="2"/><path d="M89 51h22v17H89Z" fill="#9f9f7b"/><path d="M78 64q22-12 44 0l30 36H48Z" fill="${active?'#6e896e':'#9aa58a'}" stroke="#70836a" stroke-width="1.5"/><ellipse cx="100" cy="101" rx="52" ry="10" fill="${active?'#f4e6b4':'#dcdcc4'}"/><ellipse cx="100" cy="104" rx="${8+level*5}" ry="6" fill="#fff4cd"/>${Array.from({length:level},(_,i)=>`<path d="m${78+i*22} 124-3 13" stroke="${active?'#c8ab67':'#aab195'}" stroke-width="2" stroke-linecap="round"/>`).join('')}`, '0 0 200 160');}
export function pendant(brightness=50){return svg(`<path d="M100 0v70" stroke="#687b63" stroke-width="2"/><path d="M89 66h22v18H89Z" fill="#a5ac8b"/><path d="M77 79q23-11 46 0l38 40H39Z" fill="#65816a" stroke="#4c6e57" stroke-width="1.6"/><ellipse cx="100" cy="120" rx="61" ry="12" fill="#d6d7b5"/><ellipse cx="100" cy="122" rx="52" ry="8" fill="#fff2b8" opacity="${brightness/100}"/><path d="M61 104q14-13 26-15" stroke="#9db293" stroke-width="3" stroke-linecap="round"/>`,'0 0 200 160');}
export function dimmer(value=50){const angle=-135+value*2.7;return svg(`<circle cx="80" cy="80" r="74" fill="#dce2ca" stroke="#9cab8d"/>${Array.from({length:13},(_,i)=>`<g transform="rotate(${-135+i*22.5} 80 80)"><path d="M80 17v${i%3===0?9:5}" stroke="${i<=value/100*12?'#637e53':'#aab69b'}" stroke-width="${i%3===0?2:1}"/></g>`).join('')}<circle cx="80" cy="84" r="45" fill="#526c471c"/><circle cx="80" cy="80" r="45" fill="#f0f1de" stroke="#98aa87" stroke-width="1.5"/><circle cx="80" cy="80" r="37" stroke="#d4ddc4"/><g transform="rotate(${angle} 80 80)"><path d="M80 45v17" stroke="#607c50" stroke-width="4" stroke-linecap="round"/></g><circle cx="44" cy="137" r="3" fill="#91a17f"/><circle cx="116" cy="137" r="6" fill="#bfaa70"/>`,'0 0 160 160','aria-hidden="true"');}
export function jar(s,{preview=null,soilFlight=false,water=false,celebrate=false}={}){
 const silhouette='M165 75V111C165 143 105 161 105 228V359Q105 399 280 400Q455 399 455 359V228C455 161 395 143 395 111V75Z';
 const soil=s.soil?`<g class="${soilFlight?'soil-arriving':''}"><path d="M110 321q170 42 340 0v42q-170 62-340 0Z" fill="${SOILS[s.soil].color}"/><ellipse cx="280" cy="322" rx="170" ry="32" fill="${SOILS[s.soil].color}"/><path d="M110 338q170 46 340 0v28q-170 61-340 0Z" fill="#27291c" opacity="${s.moisture/210}"/>${Array.from({length:58},(_,i)=>`<circle cx="${124+i*53%310}" cy="${306+i*17%67}" r="${1+i%3}" fill="${i%3?'#bca57b':'#4e4433'}" opacity=".55"/>`).join('')}</g>`:'';
 const flora=[1,2,0].map(i=>{const p=s.plants[i];if(!p)return '';return `<g transform="translate(${[190,282,366][i]} ${[326,315,328][i]}) scale(${p.growth*.91})"><g class="growing-plant" style="--sway:${i%2?1:-1}deg"><g transform="rotate(${p.health<45?(i%2?13:-16):0})">${plant(p.species,p.health)}</g></g></g>`;}).join('');
 const ghost=preview?.kind==='plant'&&s.soil?`<g transform="translate(280 320) scale(.9)" opacity=".25">${plant(preview.type)}</g>`:'';
 const creatures=s.creatures.map((c,k)=>Array.from({length:c==='springtails'?4:2},(_,i)=>`<g transform="translate(${177+i*56+k*27} ${346+k*14})"><g class="crawling-bug" style="animation-delay:-${i*2}s">${bug(c,0,0,c==='springtails'?.19:.27)}</g></g>`).join('')).join('');
 const drops=Array.from({length:21},(_,i)=>`<path d="M${128+i*47%300} ${180+i*31%150}q-5 9 0 10q5-1 0-10Z" fill="#ecf4e8" stroke="#b9d4c5" opacity="${s.soil?Math.max(0,(s.moisture-40)/80):0}"/>`).join('');
 return svg(`<defs><linearGradient id="bottle-glass"><stop stop-color="#c9ded1" stop-opacity=".5"/><stop offset=".38" stop-color="#fff" stop-opacity=".12"/><stop offset="1" stop-color="#a9cbb9" stop-opacity=".35"/></linearGradient><linearGradient id="bottle-shine"><stop stop-color="#fff" stop-opacity=".85"/><stop offset="1" stop-color="#fff" stop-opacity=".05"/></linearGradient><clipPath id="bottle-clip"><path d="${silhouette}"/></clipPath></defs><ellipse cx="280" cy="402" rx="183" ry="17" fill="#3f5843" opacity=".09"/><path d="${silhouette}" fill="url(#bottle-glass)" stroke="#91b3a1" stroke-width="2.3"/><g clip-path="url(#bottle-clip)">${soil}${flora}${ghost}${creatures}<path d="M100 82h360v322H100Z" fill="#203a31" opacity="${(100-s.light)*.0012}"/>${drops}${water?`<g class="water-mist">${Array.from({length:30},(_,i)=>`<path d="M${180+i*31%210} ${102+i*17%90}v8" stroke="#8cbcab" stroke-width="2" stroke-linecap="round"/>`).join('')}</g>`:''}</g><path d="M152 190q-26 32-26 75v57" stroke="url(#bottle-shine)" stroke-width="14" stroke-linecap="round"/><path d="M431 244v75" stroke="white" stroke-width="5" stroke-linecap="round" opacity=".5"/><ellipse cx="280" cy="75" rx="115" ry="18" fill="#d8e6d5" fill-opacity=".5" stroke="#98b7a0" stroke-width="2"/><ellipse cx="280" cy="75" rx="104" ry="12" fill="#728f71" fill-opacity=".15" stroke="#b6cbb1"/>${celebrate?'<g fill="#d6c17b"><path d="m164 142 3 9 9 3-9 3-3 9-3-9-9-3 9-3Z"/><path d="m402 173 3 9 9 3-9 3-3 9-3-9-9-3 9-3Z"/></g>':''}`, '0 0 560 440','aria-hidden="true"');
}
